    "description": "Send a message to a user.",
    "parameters": {
      "receiver_id": "string",
      "message": "string"
    }
  },
  "view_messages_sent": {
    "description": "View all historical messages sent by the current user.",
    "parameters": {}
  },
  "cat": {
    "description": "Display the contents of a file of any extension from currrent directory.",
    "parameters": {
      "file_name": "string"
    }
